functions.after:
method = selectPaymentMethod(customer.savedMethods, customer.preference)
request = buildPaymentRequest(method, amount, customer.billingAddress, idempotencyKeyFor(customer.id, retry))
result = paymentGateway.authorize(request)
if result.requiresAction:
  return { failed: true, reason: result.actionReason }
return { failed: false, transactionId: result.transactionId, amount: amount }

items = cart.items.map(item => describePurchasedItem(item.sku, item.quantity, item.unitPrice))
receipt = { transactionId: payment.transactionId, customerId: customer.id, items: items }
if includeTaxBreakdown:
  receipt.tax = calculateTaxByJurisdiction(cart, customer.shippingAddress)
return receipt
